// 128x64
const velocimetro = atob(
  "",
);

const POT = 35;

I2C1.setup();
let oled = require("SSD1306").connect(I2C1);

setInterval(function () {
    let pot = analogRead(POT);
    let angle = pot * 240 - 210
    let rad = angle * Math.PI / 180
    let x0 = 58
    let y0 = 32
    let x1 = 20 * Math.cos(rad) + 58
    let y1 = 20 * Math.sin(rad) + 32
    console.log(angle);
    oled.clear();
    oled.drawImage(velocimetro, 0, 0);
    oled.drawLine(x0, y0, x1, y1);
    oled.flip();
}, 100);
